<!doctype html>
<html lang="sw"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashibodi ya Shemasi</title>
<style>
:root{--ink:#18213d;--green:#159b62;--pale:#f5f7fb;--line:#e3e9f2;--muted:#75829a;--red:#b42318}*{box-sizing:border-box}body{margin:0;background:var(--pale);font:14px system-ui;color:#26314a}.app{display:grid;grid-template-columns:240px 1fr;min-height:100vh}.side{padding:24px 14px;background:#fff;border-right:1px solid var(--line);overflow:auto}.brand{font-size:18px;font-weight:800;padding:5px 12px 26px;color:var(--ink)}.nav{display:block;width:100%;background:transparent;border:0;padding:11px 12px;border-radius:8px;text-align:left;color:#63708a;font-weight:650;cursor:pointer}.nav:hover,.nav.active{background:#e8fbf1;color:#13794d}.label{margin:20px 12px 7px;font-size:10px;font-weight:800;color:#9da7b9;letter-spacing:.08em}.main{max-width:1350px;width:100%;margin:auto;padding:0 30px 32px}.top{min-height:82px;display:flex;justify-content:space-between;align-items:center;gap:16px;border-bottom:1px solid var(--line)}h1,h2,h3{color:var(--ink)}h1{font-size:21px;margin:4px 0}h2{margin-top:0}.eyebrow{font-size:10px;letter-spacing:.1em;font-weight:800;color:var(--green)}.user{display:flex;gap:10px;align-items:center}.avatar{width:38px;height:38px;display:grid;place-items:center;border-radius:50%;background:#e7f8ef;color:#13794d;font-weight:800;overflow:hidden;flex:0 0 38px}.avatar img{width:100%;height:100%;object-fit:cover}.logout{display:inline-flex;align-items:center;justify-content:center;min-height:38px;padding:0 13px;border:1px solid #fecaca;border-radius:8px;background:#fff7f7;color:var(--red);text-decoration:none;font-weight:750;white-space:nowrap}.panel{display:none;padding-top:25px}.panel.active{display:block}.card{background:#fff;border:1px solid var(--line);border-radius:12px;padding:20px;box-shadow:0 4px 16px #1d2a4708}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.columns{display:grid;grid-template-columns:1fr 1fr;gap:18px}.stat strong{font-size:28px;color:var(--ink);display:block;margin:7px 0}.muted{color:var(--muted)}.notice{margin-top:18px;color:#13794d}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:11px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top}.table th{font-size:11px;color:var(--muted)}input,textarea,select{width:100%;border:1px solid #d9e1ed;border-radius:8px;padding:10px;font:inherit;background:#fff}textarea{min-height:95px}.field-label{display:block;font-weight:700;margin:13px 0 6px}.button{border:0;border-radius:8px;background:var(--green);color:#fff;padding:10px 13px;font-weight:750;cursor:pointer}.badge{font-size:11px;border-radius:99px;padding:3px 8px;background:#e8fbf1;color:#13794d;font-weight:750}.empty{color:var(--muted);padding:12px 0}@media(max-width:850px){.grid{grid-template-columns:1fr 1fr}.columns{grid-template-columns:1fr}}@media(max-width:700px){.app{grid-template-columns:1fr}.side{display:flex;gap:4px;padding:12px;overflow:auto}.brand,.label{display:none}.nav{white-space:nowrap;width:auto}.main{padding:0 14px 25px}.top{min-height:72px;padding:10px 0}.top h1{font-size:18px}.user>div:not(.avatar){display:none}.grid{grid-template-columns:1fr}.table{font-size:12px}.card{padding:15px}}
</style></head><body><div class="app"><aside class="side"><div class="brand">KANISA | SHEMASI</div><button class="nav active" onclick="show('overview',this)">Dashibodi</button><div class="label">HUDUMA ZA SHEMASI</div><button class="nav" onclick="show('members',this)">Waumini niliopangiwa</button><button class="nav" onclick="show('visits',this)">🏠 Ziara</button><button class="nav" onclick="show('spiritual',this)">🙏 Ufuatiliaji wa kiroho</button><button class="nav" onclick="show('attendance',this)">📅 Mahudhurio</button><button class="nav" onclick="show('assistance',this)">🤝 Huduma za kijamii</button><button class="nav" onclick="show('preparations',this)">⛪ Maandalizi ya ibada</button><button class="nav" onclick="show('communication',this)">📢 Mawasiliano</button><button class="nav" onclick="show('reports',this)">📊 Ripoti</button></aside><main class="main"><header class="top"><div><div class="eyebrow">OFISI YA KANISA</div><h1>Dashibodi ya Shemasi</h1></div><div class="user"><div class="avatar">@if($user->avatar)<img src="{{ asset('storage/'.$user->avatar) }}">@else{{ strtoupper(substr($user->name,0,1)) }}@endif</div><div><strong>{{ $user->name }}</strong><br><small class="muted">Shemasi wa Kanisa</small></div><a class="logout" href="{{ route('logout') }}" onclick="event.preventDefault();document.getElementById('logout').submit()">Toka</a><form id="logout" method="post" action="{{ route('logout') }}">@csrf</form></div></header>@if(session('success'))<div class="card notice">✓ {{ session('success') }}</div>@endif @if($errors->any())<div class="card" style="margin-top:18px;color:var(--red)">{{ $errors->first() }}</div>@endif

<section id="overview" class="panel active"><h2>Karibu, Shemasi</h2><p class="muted">Simamia waumini uliopangiwa, ziara, mahitaji ya kijamii na huduma za ibada.</p><div class="grid"><div class="card stat"><span>Waumini niliopangiwa</span><strong>{{ $assignedMembers->count() }}</strong></div><div class="card stat"><span>Ziara zilizorekodiwa</span><strong>{{ $visits->count() }}</strong></div><div class="card stat"><span>Ufuatiliaji unaoendelea</span><strong>{{ $followUps->where('status','!=','imekamilika')->count() }}</strong></div></div></section>

