<section id="spiritual" class="panel"><h2>🙏 Ufuatiliaji wa kiroho</h2><div class="columns"><div class="card"><h3>Ongeza ufuatiliaji</h3><form method="post" action="{{ route('church-office.deacon.follow-ups.store') }}">@csrf<label class="field-label">Muumini</label><select name="member_id" required><option value="">Chagua muumini</option>@foreach($assignedMembers as $assignment)<option value="{{ $assignment->member_id }}">{{ $assignment->member?->name }}</option>@endforeach</select><label class="field-label">Hali</label><select name="status"><option value="open">Mpya</option><option value="endelea">Inaendelea</option><option value="imekamilika">Imekamilika</option></select><label class="field-label">Maelezo / hitaji la kiroho</label><textarea name="notes" required></textarea><label class="field-label">Tarehe ya kufuatilia</label><input type="date" name="next_follow_up_on"><p></p><button class="button">Hifadhi ufuatiliaji</button></form></div><div class="card"><h3>Orodha ya ufuatiliaji</h3>@forelse($followUps as $item)<p><strong>{{ $item->member?->name }}</strong> <span class="badge">{{ $item->status }}</span><br><span class="muted">{{ $item->notes }} @if($item->next_follow_up_on)· {{ $item->next_follow_up_on->format('d/m/Y') }}@endif</span></p><hr style="border:0;border-top:1px solid var(--line)">@empty<p class="empty">Hakuna ufuatiliaji bado.</p>@endforelse</div></div></section>

<section id="attendance" class="panel"><h2>📅 Mahudhurio</h2>@if($user->can_record_attendance)<div class="columns"><div class="card"><h3>Rekodi mahudhurio</h3><form method="post" action="{{ route('church-office.attendance.store') }}">@csrf<label class="field-label">Tarehe</label><input type="date" name="service_date" value="{{ now()->format('Y-m-d') }}" required><label class="field-label">Ibada</label><input name="service_name" required placeholder="Mfano: Ibada ya Jumapili"><label class="field-label">Wanaume</label><input type="number" min="0" name="male_count" value="0" required><label class="field-label">Wanawake</label><input type="number" min="0" name="female_count" value="0" required><label class="field-label">Watoto</label><input type="number" min="0" name="children_count" value="0"><label class="field-label">Maelezo</label><textarea name="notes"></textarea><p></p><button class="button">Hifadhi mahudhurio</button></form></div><div class="card"><h3>Mahudhurio ya karibuni</h3>@forelse($attendances as $attendance)<p><strong>{{ $attendance->service_name }}</strong> — {{ $attendance->male_count+$attendance->female_count+$attendance->children_count }}<br><span class="muted">{{ $attendance->service_date->format('d/m/Y') }}</span></p>@empty<p class="empty">Hakuna mahudhurio.</p>@endforelse</div></div>@else<div class="card"><strong>Hujaruhusiwa kurekodi mahudhurio.</strong><p class="muted">Wasiliana na Katibu au Mchungaji ili ruhusa iwekwe kwenye akaunti yako.</p></div>@endif</section>

